package ai

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// Reference: pi v1.5.0 f9a26365 packages/ai/test/validation-probes.test.ts.
// The fixture is generated by that test's dump block; see testdata/README.
func TestValidateToolArgumentsPiSchemaCorpus(t *testing.T) {
	data, err := os.ReadFile("testdata/validation-pi/probes.json")
	if err != nil {
		t.Fatal(err)
	}
	var probes []struct {
		Key    string          `json:"key"`
		Name   string          `json:"name"`
		Schema json.RawMessage `json:"schema"`
		Arg    json.RawMessage `json:"arg"`
		Actual string          `json:"actual"`
	}
	if err := json.Unmarshal(data, &probes); err != nil {
		t.Fatal(err)
	}
	if len(probes) < 100 {
		t.Fatalf("corpus has %d probes; want the full serializable set", len(probes))
	}
	for _, probe := range probes {
		t.Run(probe.Key, func(t *testing.T) {
			got, err := ValidateToolArguments(
				Tool{Name: probe.Name, Parameters: probe.Schema},
				ToolCall{Name: probe.Name, Arguments: probe.Arg},
			)
			var outcome string
			switch {
			case err == nil:
				outcome = "ok " + string(got)
			case strings.HasPrefix(err.Error(), "Validation failed"):
				lines := strings.Split(err.Error(), "\n")
				if len(lines) < 2 {
					t.Fatalf("validation error has no detail: %v", err)
				}
				outcome = "REJECT " + strings.TrimSpace(lines[1])
			default:
				outcome = "THROW " + strings.SplitN(err.Error(), "\n", 2)[0]
			}
			if outcome != probe.Actual {
				t.Fatalf("got %s\nwant %s", outcome, probe.Actual)
			}
		})
	}
}
